-- #include executes this file in its own Lua chunk. Keep its runtime
-- adapter self-contained instead of depending on parent-file locals.
local _generatedSizes = {
    S = { laserRange = 280.0, kineticRange = 320.0 },
    M = { laserRange = 390.0, kineticRange = 430.0 },
    L = { laserRange = 560.0, kineticRange = 610.0 },
}

local function _generatedIcon(name)
    return "MOD/gfx/ui/weapon_icons/stellaris/" .. tostring(name) .. ".png"
end

local function _generatedDefineRay(definition)
    if weaponData[definition.weaponType] == nil then weaponDefineRay(definition) end
end

local function _generatedDefineProjectile(definition)
    if weaponData[definition.weaponType] == nil then weaponDefineProjectile(definition) end
end

local function _generatedDefineGuided(definition)
    if weaponData[definition.weaponType] == nil then weaponDefineGuided(definition) end
end

local function _generatedDefineCraft(definition)
    if weaponData[definition.weaponType] == nil then weaponDefineStrikeCraft(definition) end
end

for _, item in ipairs(_generatedStellarisWeapons) do
    local existing = nil
    for weaponType, definition in pairs(weaponData) do
        if definition.officialComponentId == item.component then existing = weaponType break end
    end
    if existing == nil then
        local size = _generatedSizes[item.slot] or _generatedSizes.M
        local common = {
            weaponType = item.id, displayName = item.zh, englishName = item.en,
            slotTypes = { item.slot }, iconPath = _generatedIcon(item.icon),
            damageMin = item.damageMin, damageMax = item.damageMax, powerUse = item.powerUse,
            shieldFix = item.shieldFix, armorFix = item.armorFix, bodyFix = item.bodyFix,
            shieldPenetration = item.shieldPenetration, armorPenetration = item.armorPenetration,
            officialComponentId = item.component, catalogTier = 10, family = item.family,
            aimControlMode = item.slot == "H" and "fixed" or "camera_limited",
            aimLimitDeg = item.slot == "H" and 0.0 or 70.0,
            aimPitchOffsetDeg = item.slot == "H" and 0.0 or 6.0,
            salvoProfile = { groupSize = 1, sequence = "sequential", interval = 0.12 },
        }
        if item.family == "strike_craft" then
            common.cooldown = 20.0; common.prefabPath = "MOD/prefabs/gammaStrikeCraft.xml"
            common.cruiseSpeed = 130.0; common.attackSpeed = 155.0; common.breakSpeed = 140.0
            common.returnSpeed = 115.0; common.dockSpeed = 18.0; common.emergencySpeed = 80.0
            common.spawnForwardOffset = 5.0; common.attackDuration = 10.0; common.craftLifetime = 26.0
            common.returnTimeout = 10.0; common.launchSpeedFactor = 0.86; common.minimumControlFactor = 0.82
            common.maxAcceleration = 700.0; common.maxDeceleration = 850.0; common.turnBlendRate = 2.70
            common.maxAngularVelocity = 28.0; common.maxAngularImpulse = 5000.0; common.craftRadius = 1.60
            common.farProbeDistance = 120.0; common.nearSweepLookahead = 0.42; common.emergencyDuration = 0.65
            common.recoverRadius = 35.0; common.fireInterval = 0.16; common.maxRange = 280.0
            common.controllerType = "strikeCraft"; common.mountProfile = "hHangar"
            common.soundProfileId = "gammaStrikeCraft"; common.fxProfile = "strikeCraft"
            _generatedDefineCraft(common)
        elseif item.family == "missile" then
            common.cooldown = 8.0; common.maxRange = 900.0; common.cruiseSpeed = 115.0; common.turnRate = 3.0
            common.prefabPath = "MOD/prefabs/swarmerMissile.xml"
            common.mountProfile = item.slot == "G" and "gRocket" or "mSwarmer"
            common.soundProfileId = "swarmerMissile"; common.fxProfile = "guidedMissile"
            common.projectileFxVariant = "swarmerMissile"; common.fxColor = item.color
            _generatedDefineGuided(common)
        elseif item.family == "plasma" or item.family == "energy_torpedo"
            or item.family == "kinetic" or item.family == "autocannon"
            or item.family == "mass_accelerator" then
            common.cooldown = 0.0
            common.maxRange = item.slot == "X" and 750.0 or (size.kineticRange or 430.0)
            common.projectileSpeed = item.family == "energy_torpedo" and 420.0 or 170.0
            common.mountProfile = item.slot == "X" and "xSpinal"
                or (item.slot == "G" and "gNeutron"
                or (item.slot == "L" and "lKinetic" or "mKinetic"))
            common.fxProfile = item.family == "plasma" and "plasmaProjectile"
                or (item.family == "energy_torpedo" and "neutronProjectile"
                or (item.family == "mass_accelerator" and "gigaCannonProjectile" or "kineticProjectile"))
            common.projectileFxVariant = common.fxProfile; common.fxColor = item.color
            common.soundProfileId = item.family == "energy_torpedo" and "neutronLauncher" or "kineticArtillery"
            _generatedDefineProjectile(common)
        else
            common.cooldown = 1.2
            common.maxRange = item.slot == "X" and 520.0 or (size.laserRange or 390.0)
            common.mountProfile = item.slot == "X" and "xSpinal"
                or (item.slot == "L" and "lEnergy" or "mEnergy")
            common.fxProfile = item.family == "arc" and "psionicArcBeam" or "energyBeam"
            common.fxColor = item.color
            common.soundProfileId = item.family == "arc" and "focusedArcEmitter" or "mediumGammaLaser"
            _generatedDefineRay(common)
        end
    end
end

